using System;using System.IO;using System.Linq;using System.Reflection;using System.Collections.Generic;using AGSSpellchecker;
class EngineTests {
 static string root;static int count;
 [STAThread]static int Main(string[] args){root=Path.GetFullPath(args[0]);AppDomain.CurrentDomain.AssemblyResolve+=(s,e)=>{string p=Path.Combine(root,new AssemblyName(e.Name).Name+".dll");return File.Exists(p)?Assembly.LoadFrom(p):null;};try{Run();Console.WriteLine("ALL "+count+" ENGINE TESTS PASSED");return 0;}catch(Exception e){Console.WriteLine(e);return 1;}}
 static void Assert(bool condition,string message){if(!condition)throw new Exception(message);Console.WriteLine("PASS "+message);count++;}
 static void Run(){using(var engine=new OfflineProof()){var issues=engine.Check("This are a sentnce.","en-US",new string[0]);Assert(issues.Any(x=>x.Kind=="Spelling"&&x.Suggestions.Contains("sentence")),"English spelling and suggestions");Assert(issues.Any(x=>x.Kind!="Spelling"),"English grammar");foreach(var x in issues)Console.WriteLine(x.Kind+": "+x.Message);var ignored=engine.Check("This are a sentnce.","en-US",new[]{"sentnce"});Assert(!ignored.Any(x=>x.Kind=="Spelling")&&ignored.Any(x=>x.Kind!="Spelling"),"Game dictionary suppresses spelling only");Assert(engine.Check("Hello ,world!","en-US",new string[0]).Count>0,"Punctuation and spacing");Assert(engine.Check("Das ist ein Beispil.","de-DE",new string[0]).Any(x=>x.Kind=="Spelling"),"German dictionary");Assert(engine.Check("Je sui un étudaint.","fr",new string[0]).Any(x=>x.Kind=="Spelling"),"French dictionary");Assert(engine.Check("Esto es una prueva.","es",new string[0]).Any(x=>x.Kind=="Spelling"),"Spanish dictionary");var masked=engine.Check("&42 Hello %s, this are a sentnce!","en-US",new string[0]);Assert(masked.Any(x=>x.Suggestions.Contains("sentence"))&&masked.All(x=>x.Start>=4),"AGS placeholders preserve result offsets");string langs=(string)typeof(OfflineProof).GetMethod("Request",BindingFlags.NonPublic|BindingFlags.Instance).Invoke(engine,new object[]{"languages",null,5000});File.WriteAllText(Path.Combine(engine.RuntimeRoot,"languages.json"),langs);Assert(engine.Languages().Count>20,"Bundled language catalog: "+engine.Languages().Count);}}
}
